from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(7))  # D0..D6
    units = list(range(5))  # U0..U4
    supplies = list(range(3))  # S0..S2
    days = list(range(4))  # Day0..Day3

    demands = [[[36.56, 37.64, 48.4, 30.04], [47.44, 41.28, 22.5, 32.39], [22.12, 25.03, 31.73, 40.05]], [[20.11, 15.38, 47.74, 28.23], [20.14, 24.28, 37.68, 46.62], [37.04, 37.89, 18.5, 30.82]], [[18.81, 13.23, 42.71, 46.42], [15.9, 42.68, 10.68, 44.75], [34.49, 35.87, 15.68, 13.26]], [[47.24, 11.71, 23.63, 31.71], [15.93, 25.23, 12.18, 22.42], [32.14, 45.22, 15.87, 33.81]], [[33.73, 25.9, 28.89, 43.68], [28.17, 34.33, 46.28, 42.18], [36.7, 19.81, 22.53, 11.41]]]
    depot_supplies = [[[23.14, 17.23, 33.47, 32.39], [14.85, 20.43, 18.26, 37.97], [26.45, 32.85, 12.34, 21.06]], [[31.92, 21.82, 29.6, 36.45], [14.91, 33.56, 15.23, 33.88], [27.11, 19.19, 12.69, 21.93]], [[27.94, 16.98, 23.07, 36.18], [15.55, 30.36, 24.17, 27.3], [28.08, 33.99, 20.51, 21.49]], [[28.47, 19.38, 28.88, 33.54], [19.95, 35.72, 22.77, 39.76], [28.86, 34.71, 15.88, 25.02]], [[29.72, 13.87, 28.53, 37.45], [24.64, 27.86, 23.34, 36.26], [24.82, 28.09, 12.72, 17.88]], [[33.06, 15.02, 36.95, 26.76], [16.48, 31.78, 19.66, 37.65], [31.81, 19.84, 18.0, 22.58]], [[26.54, 15.08, 37.21, 37.65], [15.96, 35.56, 16.25, 24.42], [28.68, 32.19, 19.34, 25.8]]]
    transport_costs = [[1.73, 1.13, 2.88, 3.21, 2.0], [2.16, 3.18, 1.12, 4.08, 3.32], [2.73, 1.02, 4.64, 4.69, 4.93], [4.91, 1.42, 3.3, 4.46, 1.85], [3.82, 1.28, 4.68, 3.46, 4.88], [3.89, 1.27, 4.16, 4.41, 3.95], [4.29, 3.86, 1.1, 3.81, 1.17]]
    risk_costs = [[159.92, 180.35, 116.64, 96.89, 90.74], [84.08, 86.72, 163.24, 107.66, 70.44], [133.08, 116.84, 51.51, 186.14, 58.72], [129.37, 75.03, 182.28, 151.05, 75.98], [80.73, 189.35, 135.24, 109.65, 53.59], [184.53, 112.85, 53.16, 95.77, 116.72], [129.91, 170.87, 113.05, 155.19, 139.56]]
    supply_volumes = [0.67, 0.83, 0.76]
    penalty_costs = [67.44, 76.56, 73.84]
    vehicle_cost = 10.0
    vehicle_capacity = 139.0
    total_vehicles = 29

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
